import Foundation
import MCP
import WPContainerKit

/// The MCP tool catalog (schemas). Behaviors live in `MCPToolDispatch`.
enum MCPTools {
    private static func obj(_ properties: [String: Value], required: [String] = []) -> Value {
        var schema: [String: Value] = ["type": "object", "properties": .object(properties)]
        if !required.isEmpty { schema["required"] = .array(required.map { .string($0) }) }
        return .object(schema)
    }
    private static func str(_ desc: String) -> Value { ["type": "string", "description": .string(desc)] }
    private static func int(_ desc: String) -> Value { ["type": "integer", "description": .string(desc)] }
    private static func bool(_ desc: String) -> Value { ["type": "boolean", "description": .string(desc)] }
    private static func strArray(_ desc: String) -> Value {
        ["type": "array", "items": ["type": "string"], "description": .string(desc)]
    }

    static let all: [Tool] = [
        Tool(name: "wp_cli",
             description: "Run an arbitrary wp-cli command against the scoped site via a one-shot wordpress:cli container. Returns {stdout, stderr, exitCode}.",
             inputSchema: obj([
                "args": strArray("wp-cli arguments, e.g. [\"plugin\",\"list\"] (no leading 'wp')."),
                "command": str("Alternative to args: a single command string, e.g. \"plugin list\"."),
             ])),
        Tool(name: "run_tests",
             description: "Run a plugin or theme's PHPUnit tests (vendor/bin/phpunit, WP_UnitTestCase) against a site or environment, like `wp-env run tests-cli phpunit`. Uses a dedicated test schema (the site's data is never touched) and the WordPress test library for the site's WordPress version (WP_TESTS_DIR). The project directory follows the server's current directory when it is inside the instance's files, else pass `path`. Install dev dependencies first with run_command (image composer:2, command [\"composer\",\"install\"]). Auto-starts the instance. Returns {stdout, stderr, exitCode, timedOut, summary {passed, tests, assertions, failures, errors, skipped, …}, workdir, schema}.",
             inputSchema: obj([
                "path": str("Project directory in the container: absolute, or relative to /var/www/html (e.g. wp-content/plugins/my-plugin)."),
                "args": strArray("PHPUnit arguments, e.g. [\"--filter\",\"test_checkout\"]."),
                "timeout": int("Seconds before PHPUnit is stopped (default 1800)."),
                "slug": str("Site or environment slug (defaults to the scoped site)."),
             ])),
        Tool(name: "run_command",
             description: "Run a command inside a site or environment's WordPress container (php, vendor/bin/phpunit, wp), or in a one-shot container of `image` with the same mounts and environment (composer:2, node:20). The working directory follows the server's current directory when it is inside the instance's files, else /var/www/html. Auto-starts the instance. Returns {stdout, stderr, exitCode, timedOut, workdir}.",
             inputSchema: obj([
                "command": strArray("The command and its arguments, e.g. [\"vendor/bin/phpunit\",\"--testdox\"]."),
                "workdir": str("Working directory in the container: absolute, or relative to /var/www/html."),
                "image": str("Run in a one-shot container of this image, e.g. \"composer:2\"."),
                "env": strArray("Environment variables as KEY=VALUE."),
                "timeout": int("Seconds before the command is stopped (default 600; needs `sh` and `timeout` in the image)."),
                "slug": str("Site or environment slug (defaults to the scoped site)."),
             ], required: ["command"])),
        Tool(name: "read_error_log",
             description: "Read the site's error output: the WordPress container log plus a tail of wp-content/debug.log if present.",
             inputSchema: obj(["lines": int("Number of trailing lines (default 100).")])),
        Tool(name: "read_access_log",
             description: "Read the Apache access log (served on the container's stdout via `container logs`).",
             inputSchema: obj(["lines": int("Number of trailing lines (default 100).")])),
        Tool(name: "wp_debug_toggle",
             description: "Enable or disable WP_DEBUG, WP_DEBUG_LOG and SCRIPT_DEBUG via wp-cli config set.",
             inputSchema: obj([
                "enabled": bool("Turn all three debug constants on (true) or off (false)."),
                "wpDebug": bool("Override WP_DEBUG specifically."),
                "wpDebugLog": bool("Override WP_DEBUG_LOG specifically."),
                "scriptDebug": bool("Override SCRIPT_DEBUG specifically."),
             ], required: ["enabled"])),
        Tool(name: "read_wp_config",
             description: "Parse wp-config.php and return its define() constants and $table_prefix.",
             inputSchema: obj([:])),
        Tool(name: "edit_wp_config",
             description: "Set or add a wp-config.php constant (timestamped .bak backup first).",
             inputSchema: obj([
                "name": str("Constant name, e.g. WP_MEMORY_LIMIT."),
                "value": str("Value. String unless raw=true."),
                "raw": bool("Emit the value verbatim (for booleans/numbers) instead of a quoted string."),
             ], required: ["name", "value"])),
        Tool(name: "get_site_info",
             description: "Full site descriptor: paths, URL, port, status, image, DB credentials, provisioned flag, a loginHint (prefer login_link over the wp-login form), the auto-stop-when-idle timeout (idleStopMinutes / effectiveIdleStopMinutes, where 0 means never), plus active plugins & theme when running.",
             inputSchema: obj([:])),
        Tool(name: "login_link",
             description: "Mint a one-time browser login link (magic link) for the scoped site. Opening the returned URL in a browser starts a logged-in wp-admin session — no wp-login.php form, no credentials to type. The link is single-use and expires in 15 minutes. Prefer this over driving the login form.",
             inputSchema: obj([
                "user": str("WordPress user login to log in as (default: admin)."),
             ])),
        Tool(name: "create_user",
             description: "Create a WordPress user via wp-cli. Returns {user, email, role, password} — a generated password is returned when none is provided. Errors clearly if the user already exists.",
             inputSchema: obj([
                "user": str("New user login."),
                "email": str("New user email."),
                "role": str("Role (default administrator)."),
                "password": str("Password; a strong random one is generated when omitted."),
             ], required: ["user", "email"])),
        Tool(name: "site_health_check",
             description: "Health snapshot: container states, DB healthcheck, HTTP status code, WP_DEBUG state, and folder sizes.",
             inputSchema: obj([:])),
        Tool(name: "site_start",
             description: "Start the scoped site (provisioning WordPress on first run). Starts ONLY the site by default — pass with_envs to also start every worktree environment created from it.",
             inputSchema: obj([
                "with_envs": bool("Also start all worktree environments of the site (default false)."),
                "no_pull": bool("Never contact the registry; fail clearly if an image isn't already local (default false)."),
                "refresh_images": bool("Force a registry pull even for images that already exist locally; falls back to the local image with a warning if the pull fails (default false)."),
             ])),
        Tool(name: "site_stop", description: "Stop the scoped site's containers.", inputSchema: obj([:])),
        Tool(name: "site_restart", description: "Restart the scoped site.", inputSchema: obj([:])),
        Tool(name: "site_status", description: "Current status/url/port of the scoped site.", inputSchema: obj([:])),
        Tool(name: "list_sites",
             description: "List every site and worktree environment with status/url/port.",
             inputSchema: obj([:])),
        Tool(name: "worktree_create",
             description: "Create a git-worktree branch environment for a repo under a site's wp-content. By default the checkout is auto-provisioned — the parent's gitignored runtime deps (Composer vendor/, built assets like dist/, provisioned mu-plugins/plugins) are copied in so the env boots into a working site with no manual composer install / npm build (branch-tracked files are never overwritten) — and the environment's database is a schema on the parent site's existing MariaDB container, so it runs one container instead of two. The returned `url` is the environment's own hostname (`http(s)://<envSlug>.localhost`, https when the parent site uses HTTPS; resolves with no /etc/hosts entry), and `localUrl` is the equivalent http://127.0.0.1:<port>. Both are served by the WP Container reverse proxy (the environment's container publishes no port of its own), so they need the app running or `wp-container proxy serve`; a `warnings` entry says so when none is. The environment auto-stops after 180 idle minutes (3 hours) by default and is woken by the next request to that same URL — a freshly created environment still on that default gets a further 6-hour grace period during which it is never auto-stopped regardless of use (an explicit timeout set via set_idle_stop skips the grace period and applies immediately) — use set_idle_stop to change or disable it. Returns a descriptor {url, localUrl, port, path, worktreePath, branch, envSlug, containers, database}.",
             inputSchema: obj([
                "site": str("Parent site slug (defaults to the scoped site)."),
                "repo": str("Repo path relative to wordpress/, e.g. wp-content/plugins/my-plugin."),
                "branch": str("Branch name (created if missing)."),
                "from": str("Base ref when creating a new branch."),
                "provision": bool("Seed the worktree with the parent's gitignored runtime deps so it's runnable out of the box (default true). Pass false for a bare checkout."),
                "isolated_db": bool("Give the environment its own MariaDB container instead of a schema on the parent site's server (default false). Costs ~470 MB of memory; worth it only for a very large database, where cloning the parent's data directory beats a logical dump+restore."),
                "import_file": str("Absolute path to a .sql/.sql.gz dump to import into the new environment's database instead of keeping the parent's data. Runs the db_import pipeline (backup, URL migration to the environment's URL, scrub, media, admin, rollback); scrub, allowed_emails, allowed_domains, media, media_path, create_admin and source_url apply as in db_import. The result is under `import`; if it fails, the environment is kept, rolled back to the parent's data, and the tool returns an error with the environment's details and the import error under `import`."),
                "scrub": bool("With import_file: scrub personal data after import (default true)."),
                "allowed_emails": strArray("With import_file: email addresses to preserve when scrubbing."),
                "allowed_domains": strArray("With import_file: email domains to preserve when scrubbing."),
                "media": str("With import_file: \"remote\" (default), \"skip\", or \"copy\" (requires media_path)."),
                "media_path": str("With import_file: local uploads folder to copy from when media=\"copy\"."),
                "create_admin": bool("With import_file: create/reset the local admin/password login (default true)."),
                "source_url": str("With import_file: trust this URL as the dump's source instead of the detected `home` option."),
             ], required: ["repo", "branch"])),
        Tool(name: "worktree_list",
             description: "List worktree environments, optionally filtered by parent site.",
             inputSchema: obj(["site": str("Filter by parent site slug (defaults to the scoped site; pass \"*\" for all).")])),
        Tool(name: "worktree_delete",
             description: "Delete a worktree environment.",
             inputSchema: obj([
                "envSlug": str("Environment slug, e.g. my-site-wt-feature-x."),
                "keepBranch": bool("Keep the git branch (default true)."),
                "keepWorktree": bool("Keep the worktree checkout on disk (default false)."),
             ], required: ["envSlug"])),
        Tool(name: "xdebug_toggle",
             description: "Enable or disable Xdebug for the scoped site. Uses a derived Xdebug WordPress image (built lazily) and points client_host at the host gateway; restarts the site to apply when running.",
             inputSchema: obj(["enabled": bool("Turn Xdebug on (true) or off (false).")], required: ["enabled"])),
        Tool(name: "elasticsearch_toggle",
             description: "Enable or disable the per-site Elasticsearch sidecar (single-node, security off). Wires ELASTICSEARCH_URL/EP_HOST into WordPress; restarts the site to apply when running.",
             inputSchema: obj(["enabled": bool("Turn Elasticsearch on (true) or off (false).")], required: ["enabled"])),
        Tool(name: "mailpit_toggle",
             description: "Enable or disable the per-site Mailpit email catcher. When on, all outgoing WordPress mail is captured by Mailpit (SMTP) instead of being sent; browse or read it via its web UI + REST API (GET <mailboxUrl>/api/v1/messages). Writes/removes a managed mail-routing handler (in the site's private php/ folder, never the project tree) and restarts the site to apply when running. The mailbox URL is returned here and in get_site_info.",
             inputSchema: obj(["enabled": bool("Turn Mailpit on (true) or off (false).")], required: ["enabled"])),
        Tool(name: "redis_toggle",
             description: "Enable or disable the per-site Redis container for a persistent object cache. Defines WP_REDIS_HOST/WP_REDIS_PORT (unless wp-config.php defines them) for an object-cache drop-in such as the Redis Object Cache plugin, which the site must have installed and enabled (`wp redis enable`). The cache is empty after every restart. Restarts the site to apply when running.",
             inputSchema: obj(["enabled": bool("Turn Redis on (true) or off (false).")], required: ["enabled"])),
        Tool(name: "set_idle_stop",
             description: "Set how long a site or worktree environment may sit unused before the reverse proxy stops it to free its VM's memory; the next request starts it again behind a page that refreshes into the live site. ENVIRONMENTS default to 180 minutes (3 hours), with a further 6-hour grace period right after creation during which an environment STILL ON THAT DEFAULT is never auto-stopped regardless of use: the proxy serves both of an environment's URLs (its <envSlug>.localhost domain and http://127.0.0.1:<port>), so every request to either counts as activity and wakes it — as do wp-cli, MCP tool calls and magic-login. Passing an explicit `minutes` value (including 0) always wins over both the default and its grace period — it takes effect immediately, not after 6 hours. Pass 0 while you are mid-task on an environment you will leave idle for longer than that. SITES default to never: a site publishes its own port, so requests to http://127.0.0.1:<port> bypass the proxy and are invisible to the idle clock (its <slug>.localhost / custom-domain URLs are not). Omit `minutes` to restore the default (and its grace period).",
             inputSchema: obj([
                "minutes": int("Auto-stop after this many idle minutes; 0 = never. Omit to restore the built-in default (environments 180 min, sites never)."),
                "slug": str("Site or environment slug (defaults to the scoped site)."),
             ])),
        Tool(name: "db_import",
             description: "Import a .sql/.sql.gz dump into a site's or worktree environment's database: safety backup (one command away from undone) → import → URL migration (source detected from the dump's `home` option, or source_url) → optional scrub of personal data (users/comments/admin email) → media handling (remote proxy handler, folder copy, or skip) → optional local admin/password login. Works on a site or a worktree environment: an environment's import replaces only its own database and migrates URLs to the environment's URL (a dump that switches databases with USE/CREATE DATABASE is refused for an environment sharing its parent's server). Auto-starts the target if it isn't running. On failure the pre-import backup is automatically re-imported (rollback) before the error is returned. No streaming progress — returns the final summary.",
             inputSchema: obj([
                "site": str("Site or worktree environment slug (defaults to the scoped site)."),
                "file": str("Absolute path to a .sql or .sql.gz dump file."),
                "scrub": bool("Scrub personal data after import (default true)."),
                "allowed_emails": strArray("Email addresses to preserve as-is when scrubbing."),
                "allowed_domains": strArray("Email domains to preserve as-is when scrubbing."),
                "media": str("Media handling: \"remote\" (default), \"skip\", or \"copy\" (requires media_path)."),
                "media_path": str("Local uploads folder to copy from; required when media=\"copy\"."),
                "create_admin": bool("Create/reset the local admin/password login after import (default true)."),
                "source_url": str("Trust this URL as the dump's source instead of the detected `home` option."),
             ], required: ["file"])),
        Tool(name: "site_export",
             description: "Export a site to a portable .zip archive holding its database, its wordpress/ folder (docroot mounts copied in) and its environment settings. Auto-starts the site if it isn't running. Default excludes (.git, .svn, .DS_Store, __MACOSX, node_modules, bower_components) always apply; `exclude` adds more. Refuses to overwrite an existing archive unless force is true. No streaming progress: returns the final summary (archive path, size in bytes, manifest, warnings).",
             inputSchema: obj([
                "slug": str("Site slug (defaults to the scoped site). Worktree environments can't be exported."),
                "output": str("Absolute path of the .zip to write, or an existing directory to receive <slug>-<yyyyMMdd>.zip."),
                "exclude": strArray("Extra file or folder names to leave out, added to the default excludes."),
                "force": bool("Overwrite an existing archive at `output` (default false)."),
             ], required: ["output"])),
        Tool(name: "site_import",
             description: "Create a NEW, separate site from a .zip made by site_export: creates the site folder and record, extracts the files, starts the site, imports the database and migrates its URLs. Users are kept as they were. This MCP session stays scoped to its current site; use the returned slug with a new session to work on the imported site. A hosts-file failure while applying a custom domain is reported as a warning, not an error. A failure removes the partly imported site. No streaming progress: returns {slug, url, warnings}.",
             inputSchema: obj([
                "file": str("Absolute path to a .zip made by site_export."),
                "name": str("Name for the new site (default: the exported site's name)."),
                "domain": str("Custom domain for the new site, e.g. mysite.local. Omit to keep the archive's domain."),
                "no_domain": bool("Give the new site no custom domain. Cannot be combined with `domain`."),
             ], required: ["file"])),
        Tool(name: "share_start",
             description: "Share a site or worktree environment on a public URL through a tunnel provider: ngrok, cloudflared, or a custom provider. Without `provider`, the instance's saved provider is used, or else the default provider (ngrok unless changed). WARNING: the link exposes the site to the public internet; it is protected by a username and password, which this tool returns and the user must be told to pass on only to intended visitors. Auto-starts the instance. The WP Container app or `wp-container proxy serve` must be running. Turning the password off and changing password exceptions are human-only actions (`wp-container share` CLI or the app); this tool cannot do either. Exceptions saved earlier stay in force and are listed in `allow`. A share that was opened without a password is reopened with the password on. A provider failure is returned as an error with the provider's message. Returns {url, temporary, provider, username, password, instance, allow, state}.",
             inputSchema: obj([
                "slug": str("Site or environment slug (defaults to the scoped site)."),
                "provider": str("Tunnel provider: ngrok, cloudflared, or a custom provider name. Omit to keep the instance's saved provider or the default."),
                "clear_provider": bool("Forget the instance's saved provider so the share uses the default provider. Cannot be combined with `provider`."),
                "hostname": str("Fixed public hostname, when the provider supports one."),
                "reset_password": bool("Generate a new password for the share."),
             ])),
        Tool(name: "share_stop",
             description: "Stop sharing a site or worktree environment; the public URL stops working. Its saved credentials are kept for the next share_start. Returns {ok, instance}.",
             inputSchema: obj(["slug": str("Site or environment slug (defaults to the scoped site).")])),
        Tool(name: "share_status",
             description: "Show whether a site or environment is shared publicly and on which URL. Without `slug`, lists every site and environment that has share settings. The password is never included; share_start returns it. Returns a list of {instance, state, url, provider, temporary, error}.",
             inputSchema: obj(["slug": str("Site or environment slug. Omit to list all shares.")])),
    ]
}
